# Catálogo de "tipos de solución" del Banco de Evidencias (inspirado en la Plataforma de Evidencias del BID),
# organizado por los ejes de la Ley N.° 30364. Cada caso remite al N.° de la matriz. POR VALIDAR por el Observatorio.
# Efectividad: Efectivo · Prometedor · Evidencias mixtas · Sin efecto · En evaluación
# Efecto de cada caso: Positivo · Mixto · Sin efecto · Sin resultados aún
import json
EJES=[
 ('prevencion','Prevención','Acciones para evitar que la violencia ocurra: cambiar normas y estereotipos, trabajar con varones para prevenir conductas violentas y fortalecer la autonomía de las mujeres.','Ley N.° 30364, art. 27'),
 ('atencion','Atención y recuperación','Servicios que atienden a las víctimas y las ayudan a recuperarse, como los Centros Emergencia Mujer y Familia y los hogares de refugio temporal, y el cuidado de quienes las atienden.','Ley N.° 30364, arts. 27 al 29'),
 ('proteccion','Protección y sanción','Denuncia, proceso especial y medidas de protección para las víctimas, a cargo de la policía, la fiscalía y el Poder Judicial.','Ley N.° 30364, arts. 13 al 26'),
 ('reeducacion','Reeducación de personas agresoras','Tratamiento para que las personas agresoras detengan todo tipo de violencia, tanto en prisión como en libertad.','Ley N.° 30364, arts. 30 al 32'),]
SOL=[
 dict(id='transferencias',eje='prevencion',n='Transferencias monetarias condicionadas',ef='Efectivo',tipos=['Física'],
  d='Entrega periódica de dinero a hogares en pobreza a cambio de cumplir compromisos de salud y educación, como el programa JUNTOS.',
  ev='En el Perú, JUNTOS redujo entre 25% y 30% la violencia física de pareja contra las mujeres usuarias. Una revisión de 22 estudios en países de ingresos bajos y medios confirma el resultado: en 11 de 14 evaluaciones cuantitativas las transferencias redujeron la violencia de pareja.',
  casos=[(93,'Positivo'),(210,'Positivo')]),
 dict(id='hombres',eje='prevencion',n='Trabajo con hombres para transformar masculinidades',ef='Prometedor',tipos=['Física','Psicológica','Sexual'],
  d='Grupos de reflexión con hombres de la comunidad para cuestionar las ideas que justifican la violencia y promover relaciones igualitarias, como la estrategia Hombres por la Igualdad del MIMP.',
  ev='En dos ensayos aleatorios (República Democrática del Congo y Costa de Marfil) los hombres mejoraron sus actitudes y redujeron su intención de ejercer violencia. La violencia reportada por las mujeres bajó, pero sin significancia estadística.',
  casos=[(121,'Positivo'),(124,'Mixto')]),
 dict(id='celular',eje='prevencion',n='Mensajes por celular y WhatsApp',ef='Evidencias mixtas',tipos=['Sexual','Psicológica'],
  d='Mensajes de texto, voz o WhatsApp con información y ejercicios para prevenir la violencia o vincular a las personas con servicios.',
  ev='Hablemos entre Patas (Perú) redujo la violencia sexual de pareja de 22,8% a 18%. Mobile Link (Camboya) no redujo la violencia. Otra evaluación en el Perú aún no publica resultados.',
  casos=[(134,'Positivo'),(123,'Sin efecto'),(133,'Sin resultados aún')]),
 dict(id='escuelas',eje='prevencion',n='Programas en escuelas y con adolescentes',ef='Evidencias mixtas',tipos=['Física','Sexual'],
  d='Sesiones en colegios o espacios seguros con contenidos sobre relaciones sanas, habilidades para la vida y salud sexual.',
  ev='Skhokho (Sudáfrica) redujo la violencia en el enamoramiento, pero sin significancia estadística. COMPASS (niñas refugiadas en Etiopía) no redujo la violencia, aunque mejoró otros resultados.',
  casos=[(125,'Mixto'),(122,'Sin efecto')]),
 dict(id='testigos',eje='prevencion',n='Formación de testigos que intervienen',ef='Prometedor',tipos=['Sexual'],
  d='Capacitación para que las personas reconozcan situaciones de violencia sexual y sepan intervenir de forma segura.',
  ev='En un piloto en el Perú aumentó la disposición de los participantes a intervenir y bajó la aceptación de mitos sobre la violación. Falta medir si reduce la violencia.',
  casos=[(92,'Positivo')]),
 dict(id='comunidad',eje='prevencion',n='Movilización comunitaria',ef='Prometedor',tipos=['Física','Psicológica','Sexual'],
  d='Trabajo con la comunidad y sus líderes para cambiar las normas que toleran la violencia y para detectar y derivar casos.',
  ev='SASA! (Uganda) redujo la violencia física y sexual de pareja y la aceptación social de la violencia en las comunidades donde se aplicó. En el Perú hay una evaluación en curso sobre líderes comunitarios que aún no publica resultados.',
  casos=[(211,'Positivo'),(135,'Sin resultados aún')]),
 dict(id='equipos',eje='atencion',n='Cuidado de los equipos que atienden a víctimas',ef='Prometedor',tipos=['Psicológica'],
  d='Programas para prevenir el desgaste emocional del personal que atiende casos de violencia, como el de la Línea 100.',
  ev='Redujo el estrés traumático secundario de los operadores de la Línea 100, aunque no el síndrome de agotamiento profesional en general.',
  casos=[(136,'Positivo')]),
 dict(id='cem',eje='atencion',n='Centros de atención integral a víctimas',ef='Prometedor',tipos=['Física','Psicológica','Sexual'],
  d='Servicios públicos gratuitos que brindan atención legal, psicológica y social a las víctimas, como los Centros Emergencia Mujer y Familia del MIMP.',
  ev='En el Perú, la apertura de un CEM redujo la violencia de género en cerca de 10% y las muertes de mujeres por agresión en cerca de 7%, y mejoró la asistencia escolar de hijas e hijos. Es una sola evaluación de impacto.',
  casos=[(201,'Positivo')]),
 dict(id='ordenes',eje='proteccion',n='Medidas de protección',ef='Evidencias mixtas',tipos=['Física','Psicológica','Sexual'],
  d='Órdenes judiciales que prohíben al agresor acercarse o comunicarse con la víctima, entre otras medidas.',
  ev='Una revisión encontró una reducción pequeña pero significativa de la violencia. Otra, con 25 estudios, halló resultados mixtos y estudios de baja calidad; las medidas funcionan mejor cuando se acompañan de la detención del agresor. No hay evaluaciones en el Perú.',
  casos=[(212,'Positivo'),(213,'Mixto')]),
 dict(id='comisarias',eje='proteccion',n='Comisarías especializadas de mujeres',ef='Evidencias mixtas',tipos=['Física'],
  d='Comisarías dedicadas a recibir denuncias de violencia contra las mujeres, a menudo con personal femenino.',
  ev='En Brasil redujeron los homicidios de mujeres solo en zonas metropolitanas. En la India no aumentaron las denuncias y priorizaron la reconciliación con el agresor. No hay evaluaciones en el Perú.',
  casos=[(214,'Mixto'),(215,'Sin efecto')]),
 dict(id='reeducacion',eje='reeducacion',n='Programas de reeducación para personas agresoras',ef='Evidencias mixtas',tipos=['Física','Psicológica'],
  d='Tratamiento psicológico y grupal para que las personas agresoras dejen de ejercer violencia, como los Centros de Atención Institucional (CAI) del MIMP.',
  ev='Un metaanálisis de 31 estudios encontró que reducen la reincidencia hasta por dos años, pero el efecto no se sostiene después. En el Perú solo hay un estudio cualitativo del CAI, con cambios positivos pero parciales.',
  casos=[(216,'Mixto'),(207,'Sin resultados aún')]),
]
EF=['Efectivo','Prometedor','Evidencias mixtas','Sin efecto','En evaluación']
json.dump({'ejes':[dict(id=a,n=b,d=c,base=e) for a,b,c,e in EJES],'efectividad':EF,
  'soluciones':[dict(s,casos=[{'n':n,'efecto':e} for n,e in s['casos']]) for s in SOL]},
  open('data/soluciones.json','w',encoding='utf-8'),ensure_ascii=False,separators=(',',':'))
print(len(SOL),'soluciones,',sum(len(s['casos']) for s in SOL),'casos')
